// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        address owner = c.owner();
        vm.deal(owner, amount);
        Reverter reverter = new Reverter();
        uint256 balanceBefore = address(c).balance;
        bool success;
        vm.prank(owner);
        try c.sendMoney(address(reverter), amount) {
            success = true;
        } catch {
            success = false;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(
            (balanceBefore == balanceAfter && !success) ||
            (balanceAfter == balanceBefore - amount && success)
        );
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
